// --- Sauvegarde cloud (Firestore) ---
export async function loadCloud(uid) {
  const snap = await getDoc(doc(db, "users", uid));
  return snap.exists() ? snap.data() : null;
}
export async function saveCloud(uid, data) {
  return setDoc(doc(db, "users", uid), data, { merge: true });
}

// --- Suppression de compte (obligatoire Play Store) ---
export async function deleteAccount() {
  const user = auth.currentUser;
  if (!user) return;
  await deleteDoc(doc(db, "users", user.uid));
  await deleteUser(user);
}

// --- Notifications push (FCM) ---
let _messaging = null;
async function getMsg() {
  if (_messaging) return _messaging;
  if (!(await isSupported())) return null;
  _messaging = getMessaging(app);
  return _messaging;
}

// Demande la permission, enregistre le service worker, renvoie le token FCM.
// Doit être appelée depuis un geste utilisateur (clic).
export async function enableNotifications() {
  const msg = await getMsg();
  if (!msg) throw new Error("unsupported");
  if (!VAPID_KEY || VAPID_KEY.startsWith("COLLE")) throw new Error("novapid");
  const perm = await Notification.requestPermission();
  if (perm !== "granted") throw new Error("denied");
  let reg;
  try {
    reg = await navigator.serviceWorker.register("firebase-messaging-sw.js");
    await navigator.serviceWorker.ready;
  } catch (e) {
    console.error("Échec enregistrement service worker:", e);
    throw new Error("sw");
  }
  let token;
  try {
    token = await getToken(msg, { vapidKey: VAPID_KEY, serviceWorkerRegistration: reg });
  } catch (e) {
    console.error("Échec getToken:", e);
    const err = new Error("token"); err.detail = e && e.message; throw err;
  }
  if (!token) throw new Error("notoken");
  return token;
}

// Réception d'une notif quand l'app est ouverte (premier plan)
export function onForegroundMessage(cb) {
  getMsg().then(msg => { if (msg) onMessage(msg, cb); });
}

// Enregistre le token de l'appareil sous le compte (pour pouvoir cibler l'envoi)
export async function saveFcmToken(uid, token) {
  if (!uid || !token) return;
  await setDoc(doc(db, "users", uid), { fcmTokens: arrayUnion(token) }, { merge: true });
}
