// ─── PHOTOS : stockage durable sur l'appareil via IndexedDB (grande capacité) ──
const IDB_NAME = "wilddex", IDB_STORE = "photos";
const normName = s => (s||"").toLowerCase().trim();
function idbOpen() {
  return new Promise((res, rej) => {
    const r = indexedDB.open(IDB_NAME, 1);
    r.onupgradeneeded = () => {
      const db = r.result;
      if (!db.objectStoreNames.contains(IDB_STORE)) db.createObjectStore(IDB_STORE);
    };
    r.onsuccess = () => res(r.result);
    r.onerror = () => rej(r.error);
  });
}
async function idbSetPhoto(key, dataUrl) {
  try {
    const db = await idbOpen();
    return new Promise(res => {
      const tx = db.transaction(IDB_STORE, "readwrite");
      tx.objectStore(IDB_STORE).put(dataUrl, key);
      tx.oncomplete = () => res(true);
      tx.onerror = () => res(false);
    });
  } catch (e) { return false; }
}
async function idbGetAllPhotos() {
  try {
    const db = await idbOpen();
    return new Promise(res => {
      const out = {};
      const tx = db.transaction(IDB_STORE, "readonly");
      const cur = tx.objectStore(IDB_STORE).openCursor();
      cur.onsuccess = e => { const c = e.target.result; if (c) { out[c.key] = c.value; c.continue(); } else res(out); };
      cur.onerror = () => res(out);
    });
  } catch (e) { return {}; }
}

