// Fusion par morceaux (utilisée à la connexion, contre l'état EN MÉMOIRE)
function mergeCollections(localCol, cloudCol) {
  const map = new Map();
  (localCol||[]).forEach(a => { const k = normName(a && a.nom); if (k && !map.has(k)) map.set(k, a); });
  (cloudCol||[]).forEach(a => {
    const k = normName(a && a.nom);
    if (!k) return;
    if (!map.has(k)) map.set(k, a);
    else if (!map.get(k).photo && a.photo) map.set(k, a);
  });
  return [...map.values()];
}
function mergeStreak(ls, cs) {
  if (ls && cs) { const base = (cs.count > ls.count) ? cs : ls; const last = (ls.last > cs.last) ? ls.last : cs.last; return { ...base, last }; }
  return ls || cs || null;
}
function mergeDaily(l, c) {
  const out = {}; const days = new Set([...Object.keys(l||{}), ...Object.keys(c||{})]);
  days.forEach(d => { const a = (l||{})[d]||{}, b = (c||{})[d]||{}; const ks = new Set([...Object.keys(a), ...Object.keys(b)]); const m = {}; ks.forEach(k => m[k] = Math.max(a[k]||0, b[k]||0)); out[d] = m; });
  return out;
}

