// ─── SON DE CAPTURE (Web Audio API, procédural) ──────────────────────────────
let _audioCtx = null;
function playCaptureSound(rarete) {
  try {
    if (!_audioCtx) _audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    const ctx = _audioCtx;
    if (ctx.state === "suspended") ctx.resume();

    const now = ctx.currentTime;

    // Mélodie de base : petit arpège ascendant joyeux
    const notes = [523.25, 659.25, 783.99]; // Do, Mi, Sol

    // Plus l'animal est rare, plus on ajoute de notes "magiques"
    const rang = { "commun":0, "peu commun":1, "rare":2, "très rare":3, "légendaire":4 };
    const niveau = rang[(rarete||"commun").toLowerCase()] || 0;
    if (niveau >= 2) notes.push(1046.50);              // Do aigu
    if (niveau >= 3) notes.push(1318.51);              // Mi aigu
    if (niveau >= 4) notes.push(1567.98, 2093.00);     // Sol + Do très aigu

    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = niveau >= 4 ? "triangle" : "sine";
      osc.frequency.value = freq;

      const start = now + i * 0.09;
      const dur = 0.22;
      gain.gain.setValueAtTime(0, start);
      gain.gain.linearRampToValueAtTime(0.25, start + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.001, start + dur);

      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(start);
      osc.stop(start + dur);
    });

    // Pour les légendaires : petit scintillement final
    if (niveau >= 4) {
      const sparkle = ctx.createOscillator();
      const sg = ctx.createGain();
      sparkle.type = "sine";
      sparkle.frequency.setValueAtTime(2093, now + 0.6);
      sparkle.frequency.exponentialRampToValueAtTime(3136, now + 0.85);
      sg.gain.setValueAtTime(0.15, now + 0.6);
      sg.gain.exponentialRampToValueAtTime(0.001, now + 0.9);
      sparkle.connect(sg);
      sg.connect(ctx.destination);
      sparkle.start(now + 0.6);
      sparkle.stop(now + 0.9);
    }
  } catch (e) {
    // Si l'audio échoue, on ignore silencieusement
  }
}

// ─── SON DE RÉCOMPENSE DÉFI (petite fanfare victorieuse) ─────────────────────
function playRewardSound() {
  try {
    if (!_audioCtx) _audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    const ctx = _audioCtx;
    if (ctx.state === "suspended") ctx.resume();
    const now = ctx.currentTime;
    // Fanfare : Do - Fa - Sol - Do aigu
    const notes = [523.25, 698.46, 783.99, 1046.50];
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "square";
      osc.frequency.value = freq;
      const start = now + i * 0.12;
      const dur = i === notes.length-1 ? 0.4 : 0.14;
      gain.gain.setValueAtTime(0, start);
      gain.gain.linearRampToValueAtTime(0.18, start + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.001, start + dur);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(start); osc.stop(start + dur);
    });
  } catch (e) {}
}

// ─── RETOUR HAPTIQUE (vibration selon rareté) ────────────────────────────────
function vibrateCapture(rarete) {
  try {
    if (!("vibrate" in navigator)) return;
    const patterns = {
      "commun":      [40],
      "peu commun":  [40, 60, 40],
      "rare":        [50, 60, 50, 60, 50],
      "très rare":   [60, 50, 60, 50, 100],
      "légendaire":  [80, 50, 80, 50, 80, 50, 150],
    };
    navigator.vibrate(patterns[(rarete||"commun").toLowerCase()] || [40]);
  } catch (e) {
    // ignore si non supporté
  }
}

// ─── PARTAGE DE FICHE (génère une carte image via canvas) ────────────────────
async function shareCard(animal) {
  try {
    const r = getRarity(animal.rarete);
    const W = 600, H = 800;
    const canvas = document.createElement("canvas");
    canvas.width = W; canvas.height = H;
    const ctx = canvas.getContext("2d");

    // Fond dégradé
    const grad = ctx.createLinearGradient(0, 0, 0, H);
    grad.addColorStop(0, "#f0faf0");
    grad.addColorStop(1, "#e3f2fd");
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);

    // Bordure couleur rareté
    ctx.strokeStyle = r.color;
    ctx.lineWidth = 16;
    ctx.strokeRect(8, 8, W - 16, H - 16);

    // Bandeau titre
    ctx.fillStyle = r.color;
    ctx.fillRect(24, 24, W - 48, 70);
    ctx.fillStyle = "white";
    ctx.font = "bold 34px sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("🌿 WildDex", W / 2, 70);

    // Photo de l'animal (carrée, centrée)
    const img = new Image();
    img.src = animal.photo;
    await new Promise(res => { img.onload = res; img.onerror = res; });
    const imgSize = 360;
    const ix = (W - imgSize) / 2, iy = 120;
    ctx.save();
    ctx.beginPath();
    ctx.roundRect(ix, iy, imgSize, imgSize, 24);
    ctx.clip();
    // crop centré
    const ratio = Math.max(imgSize / img.width, imgSize / img.height);
    const dw = img.width * ratio, dh = img.height * ratio;
    ctx.drawImage(img, ix + (imgSize - dw) / 2, iy + (imgSize - dh) / 2, dw, dh);
    ctx.restore();
    ctx.strokeStyle = r.color;
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.roundRect(ix, iy, imgSize, imgSize, 24);
    ctx.stroke();

    // Nom
    ctx.fillStyle = "#2d3436";
    ctx.font = "bold 40px sans-serif";
    ctx.fillText(animal.nom || "Animal", W / 2, 540);

    // Nom scientifique
    ctx.fillStyle = "#636e72";
    ctx.font = "italic 22px sans-serif";
    ctx.fillText(animal.nom_scientifique || "", W / 2, 572);

    // Rareté
    ctx.fillStyle = r.color;
    ctx.font = "bold 26px sans-serif";
    ctx.fillText("★ " + r.label, W / 2, 620);

    // Infos
    ctx.fillStyle = "#2d3436";
    ctx.font = "20px sans-serif";
    ctx.fillText(`${animal.type || ""}  •  ${animal.habitat || ""}`, W / 2, 660);
    ctx.fillText(`${animal.taille || ""}  •  ${animal.poids || ""}`, W / 2, 690);

    // Pied de page
    ctx.fillStyle = "#aaa";
    ctx.font = "18px sans-serif";
    ctx.fillText("Capturé le " + (animal.date || ""), W / 2, 750);

    // Convertit en blob
    const blob = await new Promise(res => canvas.toBlob(res, "image/png"));
    const file = new File([blob], `wilddex-${animal.nom || "animal"}.png`, { type: "image/png" });

    // Partage natif si dispo (mobile), sinon téléchargement
    if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({
        files: [file],
        title: `J'ai découvert un ${animal.nom} !`,
        text: `Regarde ma découverte WildDex : ${animal.nom} 🌿`,
      });
    } else {
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = file.name;
      a.click();
      URL.revokeObjectURL(url);
    }
  } catch (e) {
    console.error("Partage échoué:", e);
  }
}

