// Retourne le palier atteint si le compteur correspond exactement, sinon null
function streakRewardFor(count) {
  return STREAK_REWARDS.find(r => r.days === count) || null;
}
// Prochain palier à viser
function nextStreakReward(count) {
  return STREAK_REWARDS.find(r => r.days > count) || null;
}

