// ─── ÉCRAN COMPTE (connexion / inscription / cloud) ───────────────────────────
function AccountView({ user, onBack }) {
  const [mode, setMode] = useState("login"); // "login" | "register"
  const [email, setEmail] = useState("");
  const [pwd, setPwd]     = useState("");
  const [busy, setBusy]   = useState(false);
  const [err, setErr]     = useState(null);
  const [notif, setNotif] = useState("idle"); // idle | on | denied | unsupported
  const [fcmToken, setFcmToken] = useState(null);
  const doEnable = async (silent) => {
    if (!silent) { setErr(null); setBusy(true); }
    try {
      const t = await enableNotifications();
      await saveFcmToken(user.uid, t);   // n'est atteint QUE si le token existe vraiment
      setFcmToken(t);
      console.log("WildDex FCM — uid:", user.uid, "token:", t);
      setNotif("on");
    } catch (e) {
      if (e.message === "denied") { setNotif("denied"); }
      else if (silent) { /* échec discret au chargement : on laisse le bouton disponible */ }
      else if (e.message === "unsupported") { setNotif("unsupported"); setErr("Notifications non supportées sur cet appareil (sur iPhone, installe d'abord l'app sur l'écran d'accueil)."); }
      else if (e.message === "novapid") { setErr("Clé VAPID manquante : colle-la dans firebase.js."); }
      else if (e.message === "sw") { setErr("Service worker introuvable. Vérifie firebase-messaging-sw.js dans public/."); }
      else if (e.message === "token") { setErr("Ton navigateur bloque la création du token (fréquent sur Brave). Essaie sur Chrome. " + (e.detail || "")); }
      else { setErr("Erreur : " + (e.message || "inconnue")); }
    }
    if (!silent) setBusy(false);
  };
  const enableNotif = () => doEnable(false);
  // Au chargement : si la permission est déjà accordée, on récupère/enregistre le token pour de vrai
  useEffect(() => {
    if (!user) return;
    if (typeof Notification === "undefined") { setNotif("unsupported"); return; }
    if (Notification.permission === "denied") { setNotif("denied"); return; }
    if (Notification.permission === "granted") { doEnable(true); }
  }, []);

  const lcdBox = {
    background:"#8FA869",border:"4px solid #3a3f30",borderRadius:8,
    padding:"14px",position:"relative",overflow:"hidden",marginBottom:14,
    boxShadow:"inset 0 0 14px rgba(0,0,0,0.3)",
  };
  const scan = (
    <div style={{position:"absolute",inset:0,pointerEvents:"none",
      background:"repeating-linear-gradient(0deg, rgba(0,0,0,0.06) 0px, rgba(0,0,0,0.06) 1px, transparent 1px, transparent 3px)"}}/>
  );
  const label = {fontFamily:"'Press Start 2P',monospace",fontSize:9,color:"#2B3320",marginBottom:12,position:"relative"};
  const inputStyle = {
    width:"100%",padding:"10px",marginBottom:8,position:"relative",
    border:"2px solid #2B3320",borderRadius:4,background:"rgba(244,240,228,0.85)",
    fontFamily:"'VT323',monospace",fontSize:18,color:"#2B3320",
  };
  const btnLight = {
    width:"100%",padding:"12px",
    background:"linear-gradient(180deg,#F4F0E4,#d8d2c0)",
    border:"3px solid #3a3f30",borderRadius:8,
    fontFamily:"'Press Start 2P',monospace",fontSize:10,color:"#2B3320",
    cursor:"pointer",boxShadow:"0 4px 0 #3a3f30",marginBottom:10,
  };

  const doEmail = async () => {
    setErr(null);
    if (!email || !pwd) { setErr("Remplis l'e-mail et le mot de passe."); return; }
    if (pwd.length < 6) { setErr("Mot de passe : 6 caractères minimum."); return; }
    setBusy(true);
    try {
      if (mode === "register") await registerEmail(email.trim(), pwd);
      else await loginEmail(email.trim(), pwd);
    } catch (e) { setErr(authError(e)); }
    setBusy(false);
  };
  const doGoogle = async () => {
    setErr(null); setBusy(true);
    try { await loginGoogle(); } catch (e) { setErr(authError(e)); }
    setBusy(false);
  };
  const doLogout = async () => { setBusy(true); try { await logout(); } catch(e){} setBusy(false); };
  const doDelete = async () => {
    if (!window.confirm("Supprimer définitivement ton compte et tes données dans le cloud ?\n\nTa collection sur CET appareil sera conservée.")) return;
    setBusy(true); setErr(null);
    try { await deleteAccount(); }
    catch (e) {
      if (e && e.code === "auth/requires-recent-login")
        setErr("Sécurité : déconnecte-toi puis reconnecte-toi juste avant de supprimer le compte.");
      else setErr(authError(e));
    }
    setBusy(false);
  };

  return (
    <div style={{padding:"4px 16px 20px"}}>
      <div style={{
        background:"linear-gradient(150deg,#D7363B 0%,#B82A2F 100%)",
        border:"3px solid #9E2B2F",borderRadius:"12px 12px 8px 8px",
        padding:"12px 14px",marginBottom:14,
        boxShadow:"inset 0 2px 0 rgba(255,255,255,0.25), 0 4px 12px rgba(0,0,0,0.25)",
      }}>
        <span style={{fontFamily:"'Press Start 2P',monospace",fontSize:12,color:"#F4F0E4",textShadow:"2px 2px 0 #7a1f23"}}>
          MON COMPTE
        </span>
      </div>

      {user ? (
        <>
          <div style={lcdBox}>
            {scan}
            <div style={label}>☁️ CONNECTÉ</div>
            <div style={{fontFamily:"'VT323',monospace",fontSize:20,color:"#2B3320",position:"relative",wordBreak:"break-all"}}>
              {user.email || "Compte Google"}
            </div>
            <div style={{fontFamily:"'VT323',monospace",fontSize:16,color:"#3a4528",position:"relative",marginTop:6}}>
              Ta collection est sauvegardée dans le cloud et synchronisée sur tous tes appareils.
            </div>
          </div>

          {notif === "on" ? (
            <div style={{marginBottom:10}}>
              <div style={{textAlign:"center",padding:"12px",background:"#8FA869",border:"3px solid #3a3f30",borderRadius:8,fontFamily:"'Press Start 2P',monospace",fontSize:9,color:"#2B3320"}}>
                🔔 NOTIFICATIONS ACTIVÉES
              </div>
            </div>
          ) : notif === "denied" ? (
            <div style={{marginBottom:10}}>
              <div style={{background:"#7a1f23",border:"2px solid #3a3f30",borderRadius:6,padding:"10px 12px",marginBottom:8,fontFamily:"'VT323',monospace",fontSize:16,color:"#F4F0E4",lineHeight:1.25}}>
                🔕 Notifications bloquées par le navigateur. Pour les réactiver : clique sur l'icône à gauche de l'adresse du site → Notifications → Autoriser, puis recharge la page. (Vider le cache ne suffit pas.)
              </div>
              <button onClick={enableNotif} disabled={busy} style={{
                width:"100%",padding:"11px",
                background:"linear-gradient(180deg,#f1c40f,#e0a800)",border:"3px solid #b8860b",borderRadius:8,
                fontFamily:"'Press Start 2P',monospace",fontSize:9,color:"#2B3320",cursor:"pointer",boxShadow:"0 4px 0 #b8860b",
              }}>RÉESSAYER</button>
            </div>
          ) : (
            <button onClick={enableNotif} disabled={busy} style={{
              width:"100%",padding:"12px",marginBottom:10,
              background:"linear-gradient(180deg,#f1c40f,#e0a800)",border:"3px solid #b8860b",borderRadius:8,
              fontFamily:"'Press Start 2P',monospace",fontSize:10,color:"#2B3320",cursor:"pointer",boxShadow:"0 4px 0 #b8860b",
            }}>🔔 ACTIVER LES NOTIFICATIONS</button>
          )}
          <button onClick={doLogout} disabled={busy} style={btnLight}>SE DÉCONNECTER</button>

          <button onClick={doDelete} disabled={busy} style={{
            width:"100%",padding:"11px",marginBottom:10,
            background:"#7a1f23",border:"3px solid #3a3f30",borderRadius:8,
            fontFamily:"'Press Start 2P',monospace",fontSize:9,color:"#F4F0E4",
            cursor:"pointer",boxShadow:"0 4px 0 #3a3f30",
          }}>🗑️ SUPPRIMER MON COMPTE</button>
        </>
      ) : (
        <>
          <div style={lcdBox}>
            {scan}
            <div style={label}>{mode==="register" ? "✨ CRÉER UN COMPTE" : "🔑 SE CONNECTER"}</div>
            <input style={inputStyle} type="email" placeholder="adresse e-mail" autoCapitalize="none"
              value={email} onChange={e=>setEmail(e.target.value)} />
            <input style={inputStyle} type="password" placeholder="mot de passe (6 caractères min)"
              value={pwd} onChange={e=>setPwd(e.target.value)} />
            <button onClick={doEmail} disabled={busy} style={{...btnLight,marginBottom:0,marginTop:4}}>
              {busy ? "..." : (mode==="register" ? "CRÉER LE COMPTE" : "SE CONNECTER")}
            </button>
          </div>

          <button onClick={doGoogle} disabled={busy} style={{
            width:"100%",padding:"12px",marginBottom:10,
            background:"#F4F0E4",border:"3px solid #3a3f30",borderRadius:8,
            fontFamily:"'Press Start 2P',monospace",fontSize:9,color:"#2B3320",
            cursor:"pointer",boxShadow:"0 4px 0 #3a3f30",
            display:"flex",alignItems:"center",justifyContent:"center",gap:8,
          }}>
            <span style={{fontSize:14}}>🔵</span> CONTINUER AVEC GOOGLE
          </button>

          <button onClick={()=>{setMode(mode==="register"?"login":"register");setErr(null);}} style={{
            width:"100%",padding:"10px",marginBottom:10,background:"none",border:"none",
            fontFamily:"'VT323',monospace",fontSize:18,color:"#2B3320",cursor:"pointer",textDecoration:"underline",
          }}>
            {mode==="register" ? "J'ai déjà un compte → me connecter" : "Pas encore de compte ? → en créer un"}
          </button>
        </>
      )}

      {err && (
        <div style={{
          background:"#7a1f23",border:"2px solid #3a3f30",borderRadius:6,padding:"10px 12px",marginBottom:10,
          fontFamily:"'VT323',monospace",fontSize:17,color:"#F4F0E4",
        }}>⚠️ {err}</div>
      )}

      <button onClick={onBack} style={{
        width:"100%",padding:"10px",
        background:"#9E2B2F",border:"3px solid #3a3f30",borderRadius:8,
        fontFamily:"'Press Start 2P',monospace",fontSize:10,color:"#F4F0E4",
        cursor:"pointer",boxShadow:"0 4px 0 #3a3f30",
      }}>← RETOUR</button>
    </div>
  );
}

// ─── PROFIL / STATISTIQUES ────────────────────────────────────────────────────
async function shareProfile(p) {
  try {
    const W = 600, H = 860;
    const canvas = document.createElement("canvas"); canvas.width = W; canvas.height = H;
    const c = canvas.getContext("2d");
    c.fillStyle = "#cdd9b8"; c.fillRect(0, 0, W, H);
    c.strokeStyle = "#D7363B"; c.lineWidth = 16; c.strokeRect(8, 8, W - 16, H - 16);
    c.fillStyle = "#D7363B"; c.fillRect(24, 24, W - 48, 92);
    c.fillStyle = "#F4F0E4"; c.textAlign = "center"; c.font = "bold 38px sans-serif";
    c.fillText("🌿 MON WILDDEX", W / 2, 84);
    c.font = "84px sans-serif"; c.fillText(p.mascot, W / 2, 224);
    c.fillStyle = "#2B3320"; c.font = "bold 32px sans-serif";
    c.fillText("Niveau " + p.level + " · " + p.levelTitle, W / 2, 286);
    c.fillStyle = "#3f8b3f"; c.font = "bold 60px sans-serif";
    c.fillText(String(p.species), W / 2 - 140, 396);
    c.fillText(String(p.badges), W / 2 + 140, 396);
    c.fillStyle = "#2B3320"; c.font = "22px sans-serif";
    c.fillText("espèces", W / 2 - 140, 428);
    c.fillText("badges", W / 2 + 140, 428);
    c.font = "26px sans-serif"; c.fillText("🔥 " + p.streak + " jours de série", W / 2, 484);
    let y = 540;
    const maxC = Math.max(1, ...p.rarity.map(r => r.count));
    p.rarity.forEach(r => {
      c.textAlign = "left"; c.fillStyle = "#2B3320"; c.font = "22px sans-serif";
      c.fillText(r.label, 60, y + 19);
      c.fillStyle = "rgba(0,0,0,0.12)"; c.fillRect(250, y, 260, 24);
      c.fillStyle = r.color; c.fillRect(250, y, Math.round(260 * r.count / maxC), 24);
      c.textAlign = "right"; c.fillStyle = "#2B3320"; c.fillText(String(r.count), 540, y + 19);
      y += 44;
    });
    c.textAlign = "center"; c.fillStyle = "#5a6a44"; c.font = "22px sans-serif";
    c.fillText("Attrape-les tous sur WildDex !", W / 2, H - 44);
    const blob = await new Promise(res => canvas.toBlob(res, "image/png"));
    const file = new File([blob], "mon-wilddex.png", { type: "image/png" });
    if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({ files: [file], title: "Mon profil WildDex", text: "Voici ma collection WildDex 🌿" });
    } else {
      const url = URL.createObjectURL(blob); const a = document.createElement("a");
      a.href = url; a.download = file.name; a.click(); URL.revokeObjectURL(url);
    }
  } catch (e) { console.error("Partage profil échoué:", e); }
}

