function buildClues(a) {
  const ci = consInfo(a.statut_conservation);
  const act = (a.activite || "").toLowerCase();
  const actLabel = act.includes("nocturne") ? "nocturne"
    : act.includes("diurne") ? "diurne"
    : (act.includes("crépus") || act.includes("crepus")) ? "crépusculaire" : (a.activite || "");
  const clues = [];
  if (a.type) clues.push(`C'est un ${a.type}.`);
  if (actLabel) clues.push(`Il est plutôt ${actLabel}.`);
  if (ci) clues.push(`Statut de conservation : ${ci.label}.`);
  if (a.habitat) clues.push(`On le trouve ici : ${a.habitat}`);
  if (a.alimentation) clues.push(`Au menu : ${a.alimentation}`);
  if (a.taille) clues.push(`Il mesure environ ${a.taille}${a.poids ? `, pour ${a.poids}` : ""}.`);
  if (a.fun_fact) clues.push(`Le savais-tu ? ${a.fun_fact}`);
  if (a.nom) {
    const n = a.nom.replace(/\s/g, "").length;
    clues.push(`Son nom commence par « ${a.nom[0].toUpperCase()} » et compte ${n} lettres.`);
  }
  return clues;
}

function EnigmaView({ collection, onBack, onWin }) {
  const ready = collection.length >= 4;
  const newGame = () => {
    const t = shuffle(collection)[0];
    return {
      target: t,
      clues: buildClues(t),
      options: shuffle([t, ...shuffle(collection.filter(x => x.nom !== t.nom)).slice(0, 3)]).map(a => a.nom),
    };
  };
  const [game, setGame] = useState(() => ready ? newGame() : null);
  const [revealed, setRevealed] = useState(1);
  const [guess, setGuess] = useState(null);
  const [picking, setPicking] = useState(false);

  const pix = (sz, col) => ({ fontFamily: "'Press Start 2P',monospace", fontSize: sz, color: col });

  if (!ready) {
    return (
      <div style={{padding:"4px 16px 20px"}}>
        <div style={{background:"linear-gradient(150deg,#D7363B 0%,#B82A2F 100%)",border:"3px solid #9E2B2F",borderRadius:"12px 12px 8px 8px",padding:"12px 14px",marginBottom:14}}>
          <span style={{...pix(12,"#F4F0E4"),textShadow:"2px 2px 0 #7a1f23"}}>DEVINETTE</span>
        </div>
        <div style={{background:"#8FA869",border:"4px solid #3a3f30",borderRadius:8,padding:"20px",textAlign:"center",fontFamily:"'VT323',monospace",fontSize:20,color:"#2B3320",marginBottom:14}}>
          🕵️ Découvre au moins 4 animaux pour débloquer le mode Devinette !
        </div>
        <button onClick={onBack} style={{width:"100%",padding:"12px",background:"#9E2B2F",border:"3px solid #3a3f30",borderRadius:8,...pix(10,"#F4F0E4"),cursor:"pointer",boxShadow:"0 4px 0 #3a3f30"}}>← RETOUR</button>
      </div>
    );
  }

  const correct = guess && guess === game.target.nom;
  const points = Math.max(10, (game.clues.length - (revealed - 1)) * 10);

  const doGuess = (opt) => {
    if (guess) return;
    setGuess(opt);
    if (opt === game.target.nom) { playRewardSound(); if (onWin) onWin(points); }
    else if (navigator.vibrate) navigator.vibrate(120);
  };
  const replay = () => { setGame(newGame()); setRevealed(1); setGuess(null); setPicking(false); };

  return (
    <div style={{padding:"4px 16px 20px"}}>
      <div style={{background:"linear-gradient(150deg,#D7363B 0%,#B82A2F 100%)",border:"3px solid #9E2B2F",borderRadius:"12px 12px 8px 8px",padding:"12px 14px",marginBottom:14,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <span style={{...pix(12,"#F4F0E4"),textShadow:"2px 2px 0 #7a1f23"}}>🕵️ DEVINETTE</span>
        {!guess && <span style={pix(9,"#ffd9da")}>indice {revealed}/{game.clues.length}</span>}
      </div>

      {/* Zone indices / révélation */}
      <div style={{background:"#8FA869",border:"4px solid #3a3f30",borderRadius:8,padding:"16px",marginBottom:14,position:"relative",overflow:"hidden",boxShadow:"inset 0 0 14px rgba(0,0,0,0.3)"}}>
        <div style={{position:"absolute",inset:0,pointerEvents:"none",background:"repeating-linear-gradient(0deg, rgba(0,0,0,0.06) 0px, rgba(0,0,0,0.06) 1px, transparent 1px, transparent 3px)"}}/>
        {guess ? (
          <div style={{textAlign:"center",position:"relative"}}>
            {game.target.photo && (
              <div style={{width:120,height:120,margin:"0 auto 12px",borderRadius:8,overflow:"hidden",border:"3px solid #2B3320"}}>
                <img src={game.target.photo} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/>
              </div>
            )}
            <div style={{...pix(13, correct ? "#2e6e2e" : "#7a1f23"),marginBottom:8}}>{correct ? "✓ TROUVÉ !" : "✗ RATÉ"}</div>
            <div style={{fontFamily:"'VT323',monospace",fontSize:24,color:"#2B3320"}}>C'était : {game.target.nom}</div>
            {correct && <div style={{...pix(12,"#2e6e2e"),marginTop:10}}>+{points} XP</div>}
          </div>
        ) : (
          <div style={{position:"relative"}}>
            {game.clues.slice(0, revealed).map((c, i) => (
              <div key={i} style={{fontFamily:"'VT323',monospace",fontSize:19,color:"#2B3320",marginBottom:10,lineHeight:1.2,borderLeft:"3px solid #2B3320",paddingLeft:10}}>
                <b>Indice {i+1} :</b> {c}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Actions */}
      {!guess && !picking && (
        <div style={{display:"flex",gap:10,marginBottom:10}}>
          {revealed < game.clues.length && (
            <button onClick={()=>setRevealed(r=>r+1)} style={{flex:1,padding:"14px",background:"linear-gradient(180deg,#5b8def,#3a6fd0)",border:"3px solid #2a4f9e",borderRadius:8,...pix(10,"#F4F0E4"),cursor:"pointer",boxShadow:"0 4px 0 #2a4f9e"}}>🔎 INDICE +</button>
          )}
          <button onClick={()=>setPicking(true)} style={{flex:1,padding:"14px",background:"linear-gradient(180deg,#f1c40f,#e0a800)",border:"3px solid #b8860b",borderRadius:8,...pix(10,"#2B3320"),cursor:"pointer",boxShadow:"0 4px 0 #b8860b"}}>💡 DEVINER</button>
        </div>
      )}

      {!guess && picking && (
        <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:10}}>
          <div style={{fontFamily:"'VT323',monospace",fontSize:17,color:"#2B3320",textAlign:"center"}}>Tu paries sur… ?</div>
          {game.options.map(opt => (
            <button key={opt} onClick={()=>doGuess(opt)} style={{padding:"13px",background:"linear-gradient(180deg,#F4F0E4,#d8d2c0)",border:"3px solid #3a3f30",borderRadius:8,fontFamily:"'VT323',monospace",fontSize:19,color:"#2B3320",cursor:"pointer",boxShadow:"0 4px 0 #3a3f30",textTransform:"capitalize"}}>{opt}</button>
          ))}
          <button onClick={()=>setPicking(false)} style={{padding:"8px",background:"none",border:"none",fontFamily:"'VT323',monospace",fontSize:16,color:"#2B3320",cursor:"pointer",textDecoration:"underline"}}>← encore un indice</button>
        </div>
      )}

      {guess && (
        <button onClick={replay} style={{width:"100%",padding:"14px",marginBottom:10,background:"linear-gradient(180deg,#5fa85f,#3f8b3f)",border:"3px solid #2e6e2e",borderRadius:8,...pix(11,"#F4F0E4"),cursor:"pointer",boxShadow:"0 4px 0 #2e6e2e"}}>🔄 REJOUER</button>
      )}

      <button onClick={onBack} style={{width:"100%",padding:"8px",background:"#9E2B2F",border:"3px solid #3a3f30",borderRadius:8,...pix(9,"#F4F0E4"),cursor:"pointer",boxShadow:"0 4px 0 #3a3f30"}}>← QUITTER</button>
    </div>
  );
}

// ─── MAIN APP ─────────────────────────────────────────────────────────────────

export default function WildDex() {
  const initial = loadState() || { collection:[], streak:null, dailyDone:{}, unlockedSecrets:[], bonusXp:0 };
  const [collection, setCollection] = useState(initial.collection || []);
  const [streak, setStreak]     = useState(initial.streak || null);
  const [dailyDone, setDailyDone] = useState(initial.dailyDone || {});
  const [unlockedSecrets, setUnlockedSecrets] = useState(initial.unlockedSecrets || []);
  const [bonusXp, setBonusXp]   = useState(initial.bonusXp || 0);
  const [tab,      setTab]      = useState("home");
  const [view,     setView]     = useState("main");
  const [pending,  setPending]  = useState(null);
  const [selected, setSelected] = useState(null);
  const [justLeveledUp, setJustLeveledUp] = useState(null);
  const [challengeDone, setChallengeDone] = useState(null);
  const [streakReward, setStreakReward] = useState(null);
  const [collectionDone, setCollectionDone] = useState(null);
  const [claimedCols, setClaimedCols] = useState(() => loadClaimedCols());
  const colsInitRef = useRef(false);
  const [voiceSettings, setVoiceSettings] = useState(loadVoiceSettings());
  const [user, setUser] = useState(null);
  const syncedRef = useRef(false);

  // Contexte passé aux badges (collection + streak + secrets débloqués)
  const badgeCtx = { col:collection, streak, unlockedSecrets };

  useEffect(()=>{ saveState({ collection, streak, dailyDone, unlockedSecrets, bonusXp }); }, [collection, streak, dailyDone, unlockedSecrets, bonusXp]);
  useEffect(()=>{ saveVoiceSettings(voiceSettings); }, [voiceSettings]);

  // Au démarrage : migre les anciennes photos (localStorage) vers IndexedDB, puis les recharge
  useEffect(() => {
    let cancelled = false;
    (async () => {
      // Migration : photos encore présentes dans l'ancien format -> IndexedDB
      for (const a of (initial.collection || [])) {
        if (a && a.photo) await idbSetPhoto(normName(a.nom), a.photo);
      }
      // Hydratation : on récupère toutes les photos stockées sur l'appareil
      const photos = await idbGetAllPhotos();
      if (cancelled) return;
      setCollection(prev => prev.map(a => {
        const k = normName(a.nom);
        return photos[k] ? { ...a, photo: photos[k] } : a;
      }));
    })();
    return () => { cancelled = true; };
  }, []);

  // Authentification : suit l'état de connexion, fusionne local ↔ cloud à la connexion
  useEffect(() => {
    const unsub = watchAuth(async (u) => {
      setUser(u);
      if (u && !syncedRef.current) {
        syncedRef.current = true;
        try {
          const cloud = await loadCloud(u.uid);
          const idbPhotos = await idbGetAllPhotos();
          // Fusion contre l'état EN MÉMOIRE (le plus à jour) : une photo récente n'est jamais écrasée
          setCollection(prev => {
            const merged = mergeCollections(prev, cloud && cloud.collection);
            return merged.map(a => {
              if (a.photo) return a;
              const p = idbPhotos[normName(a.nom)];
              return p ? { ...a, photo: p } : a;
            });
          });
          setStreak(prev => mergeStreak(prev, cloud && cloud.streak));
          setBonusXp(prev => Math.max(prev||0, (cloud && cloud.bonusXp) || 0));
          setUnlockedSecrets(prev => [...new Set([...(prev||[]), ...((cloud && cloud.unlockedSecrets) || [])])]);
          setDailyDone(prev => mergeDaily(prev, cloud && cloud.dailyDone));
          // La sauvegarde cloud différée repoussera l'état fusionné automatiquement
        } catch (e) { console.warn("Synchro cloud échouée", e); }
      }
      if (!u) syncedRef.current = false;
    });
    return unsub;
  }, []);

  // Notification reçue quand l'app est ouverte (premier plan)
  useEffect(() => {
    onForegroundMessage((payload) => {
      const n = payload && payload.notification;
      if (!n) return;
      if (navigator.serviceWorker && navigator.serviceWorker.ready) {
        navigator.serviceWorker.ready
          .then(reg => reg.showNotification(n.title || "WildDex 🌿", { body: n.body || "", icon: "logo192.png" }))
          .catch(()=>{});
      }
    });
  }, []);

  // Sauvegarde cloud différée à chaque changement, si connecté
  useEffect(() => {
    if (!user) return;
    const t = setTimeout(() => {
      saveCloud(user.uid, forCloud({ collection, streak, dailyDone, unlockedSecrets, bonusXp }))
        .catch(e => console.warn("Sauvegarde cloud", e));
    }, 1500);
    return () => clearTimeout(t);
  }, [user, collection, streak, dailyDone, unlockedSecrets, bonusXp]);
  useEffect(()=>{ if (challengeDone) { playRewardSound(); if (navigator.vibrate) navigator.vibrate([60,40,60,40,120]); } }, [challengeDone]);
  useEffect(()=>{ if (streakReward) { playRewardSound(); if (navigator.vibrate) navigator.vibrate([80,40,80,40,80,40,150]); } }, [streakReward]);
  useEffect(()=>{ if (collectionDone) { playRewardSound(); if (navigator.vibrate) navigator.vibrate([60,40,60,40,120]); } }, [collectionDone]);

  // Au 1er lancement : marque silencieusement comme "déjà acquises" les collections déjà complètes
  useEffect(() => {
    if (colsInitRef.current) return;
    colsInitRef.current = true;
    if (claimedCols == null) {
      const done = COLLECTIONS.filter(c => c.progress(collection) >= c.goal).map(c => c.id);
      setClaimedCols(done); saveClaimedCols(done);
    }
  }, []);

  // Récompense quand une collection vient d'être complétée
  useEffect(() => {
    if (claimedCols == null) return;
    const newly = COLLECTIONS.filter(c => c.progress(collection) >= c.goal && !claimedCols.includes(c.id));
    if (newly.length) {
      const c = newly[0];
      setBonusXp(b => (b||0) + c.bonus);
      const next = [...claimedCols, ...newly.map(x => x.id)];
      setClaimedCols(next); saveClaimedCols(next);
      setTimeout(() => setCollectionDone(c), 500);
    }
  }, [collection, claimedCols]);

  // Sauvegarde AUTOMATIQUE dès qu'un animal est identifié
  const captureAnimal = useCallback((a, opts={}) => {
    // Sauvegarde durable de la photo sur l'appareil (IndexedDB)
    if (a && a.photo) idbSetPhoto(normName(a.nom), a.photo);
    setCollection(prev => {
      // Anti-doublon basé sur le nom normalisé
      const norm = s => (s||"").toLowerCase().trim();
      const idx = prev.findIndex(x => norm(x.nom) === norm(a.nom));
      let newCol;
      if (idx >= 0) {
        // Déjà présent : on met à jour la photo + la date, et on le remonte en tête
        const updated = { ...prev[idx], photo: a.photo || prev[idx].photo, date: a.date || prev[idx].date };
        newCol = [updated, ...prev.slice(0, idx), ...prev.slice(idx + 1)];
      } else {
        newCol = [a, ...prev];
      }

      // Calculs basés sur la collection RÉELLEMENT à jour (évite les closures périmées)
      // On lit le bonusXp courant via setBonusXp (sans le modifier) pour éviter une closure périmée
      let curBonus = 0;
      setBonusXp(b => { curBonus = b; return b; });
      const xpBefore = totalXp(prev, curBonus);
      const xpAfter = totalXp(newCol, curBonus);
      const lvlBefore = levelInfo(xpBefore).current.lvl;
      const lvlAfter = levelInfo(xpAfter).current.lvl;
      if (lvlAfter > lvlBefore) setJustLeveledUp(levelInfo(xpAfter).current);

      return newCol;
    });

    // Streak (1 fois par jour) + détection palier de récompense
    setStreak(prev => {
      const updated = updateStreak(prev);
      // Si le compteur a changé ET atteint un palier exact → récompense
      if (updated.count !== (prev?.count || 0)) {
        const reward = streakRewardFor(updated.count);
        if (reward) {
          setBonusXp(b => b + reward.bonus);
          setTimeout(()=>setStreakReward(reward), 800);
        }
      }
      return updated;
    });

    // Progression du défi du jour + détection d'accomplissement
    const ch = challengeOfTheDay();
    if (ch.check(a)) {
      setDailyDone(prev => {
        const today = todayKey();
        const before = prev[today]?.[ch.id] || 0;
        const after = before + 1;
        const need = ch.count || 1;
        // Si le défi vient d'être accompli (pas déjà fait avant), on déclenche la récompense
        if (before < need && after >= need) {
          setTimeout(()=>setChallengeDone(ch), 400);
        }
        return { ...prev, [today]: { ...(prev[today]||{}), [ch.id]: after } };
      });
    }

    // ─── Badges secrets déclenchés par événement ───
    const newSecrets = [];
    // Oiseau de nuit : scan entre minuit et 5h
    const hour = new Date().getHours();
    if (hour >= 0 && hour < 5) newSecrets.push("night_owl");
    // Éclair : 3 animaux scannés aujourd'hui
    const today = todayKey();
    setDailyDone(prev => {
      const scans = (prev[today]?._scans || 0) + 1;
      if (scans >= 3) newSecrets.push("speedy");
      return { ...prev, [today]: { ...(prev[today]||{}), _scans: scans } };
    });
    if (newSecrets.length) {
      setUnlockedSecrets(prev => {
        const merged = [...new Set([...prev, ...newSecrets])];
        // Si un nouveau secret est débloqué, petite récompense
        if (merged.length > prev.length) setTimeout(()=>playRewardSound(), 600);
        return merged;
      });
    }

    if (!opts.silent) {
      setPending(a);
      setView("result");
    }
  }, []);

  const TABS = [
    {id:"home",       icon:"🏠", label:"Accueil"},
    {id:"collection", icon:"📚", label:"Collection"},
    {id:"atlas",      icon:"🗺️", label:"Atlas"},
    {id:"badges",     icon:"⭐", label:"Badges"},
  ];

  const renderMain = () => {
    if (tab==="home")       return <HomeView collection={collection} streak={streak} dailyDone={dailyDone} unlockedSecrets={unlockedSecrets} bonusXp={bonusXp} onScan={()=>setView("scan")} onQuiz={()=>setView("quiz")} onCollections={()=>setView("collections")} onEnigma={()=>setView("enigma")}/>;
    if (tab==="collection") return <CollectionView collection={collection} onAnimalClick={a=>{setSelected(a);setView("detail");}}/>;
    if (tab==="atlas")      return <AtlasView collection={collection} onAnimalClick={a=>{setSelected(a);setView("detail");}}/>;
    if (tab==="badges")     return <BadgesView collection={collection} badgeCtx={badgeCtx}/>;
  };

  return (
    <div style={{
      minHeight:"100vh",maxWidth:480,margin:"0 auto",
      background:"#cdd9b8",
      position:"relative",fontFamily:"'Nunito',sans-serif",
      display:"flex",flexDirection:"column",
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fredoka+One&family=Nunito:wght@400;600;700;800;900&family=Press+Start+2P&family=VT323&display=swap');
        *{box-sizing:border-box;margin:0;padding:0;}
        ::-webkit-scrollbar{width:4px;}
        ::-webkit-scrollbar-thumb{background:#c8e6c9;border-radius:2px;}
        @keyframes spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}
        @keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.04)}}
        @keyframes bounce{0%{transform:translateY(0)}30%{transform:translateY(-12px)}60%{transform:translateY(-6px)}100%{transform:translateY(0)}}
        @keyframes sway0{0%,100%{transform:rotate(-3deg)}50%{transform:rotate(3deg)}}
        @keyframes sway1{0%,100%{transform:rotate(2deg)}50%{transform:rotate(-2deg)}}
        @keyframes scan{0%{top:0%}50%{top:95%}100%{top:0%}}
        @keyframes ledblink{0%,100%{opacity:1}50%{opacity:0.5}}
        @keyframes flashOut{0%{opacity:1}100%{opacity:0}}
      `}</style>

      {view==="main"&&(
        <div style={{
          background:"#2B3320",
          padding:"14px 18px",
          display:"flex",alignItems:"center",justifyContent:"space-between",
          boxShadow:"0 3px 0 #1a1f12",
          position:"sticky",top:0,zIndex:20,
        }}>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <div style={{
              width:14,height:14,borderRadius:"50%",
              background:"radial-gradient(circle at 35% 30%, #ade4ff, #2196f3 60%, #0d47a1)",
              boxShadow:"0 0 8px rgba(33,150,243,0.9)",animation:"ledblink 2s ease-in-out infinite",
            }}/>
            <span style={{fontFamily:"'Press Start 2P',monospace",fontSize:15,color:"#8FA869"}}>
              WildDex
            </span>
          </div>
          <div style={{display:"flex",alignItems:"center",gap:8}}>
            <button onClick={()=>setView("stats")} style={{
              background:"#8FA869",border:"2px solid #1a1f12",borderRadius:4,
              padding:"4px 8px",cursor:"pointer",fontSize:14,lineHeight:1,
            }}>📊</button>
            <button onClick={()=>setView("account")} style={{
              background:"#8FA869",border:"2px solid #1a1f12",borderRadius:4,
              padding:"4px 8px",cursor:"pointer",fontSize:14,lineHeight:1,
            }}>{user ? "☁️" : "👤"}</button>
            <button onClick={()=>setView("settings")} style={{
              background:"#8FA869",border:"2px solid #1a1f12",borderRadius:4,
              padding:"4px 8px",cursor:"pointer",fontSize:14,lineHeight:1,
            }}>⚙️</button>
            <div style={{
              background:"#8FA869",border:"2px solid #1a1f12",borderRadius:4,
              padding:"3px 10px",display:"flex",alignItems:"center",gap:5,
            }}>
              <span style={{fontSize:12}}>⭐</span>
              <span style={{fontFamily:"'Press Start 2P',monospace",fontSize:11,color:"#2B3320"}}>
                {computePoints(collection)}
              </span>
            </div>
          </div>
        </div>
      )}

      <div style={{flex:1,overflowY:"auto",paddingBottom:view==="main"?80:20}}>
        {view==="main"   && renderMain()}
        {view==="scan"   && <ScanView onBack={()=>setView("main")} onResult={a=>captureAnimal(a)}/>}
        {view==="result" && pending && (
          <ResultView
            animal={pending} isNew={true}
            voiceSettings={voiceSettings}
            onBack={()=>{setPending(null);setView("main");}}
          />
        )}
        {view==="detail" && selected && (
          <ResultView
            animal={selected} isNew={false}
            voiceSettings={voiceSettings}
            onBack={()=>{setSelected(null);setView("main");}}
          />
        )}
        {view==="settings" && (
          <SettingsView
            voiceSettings={voiceSettings}
            onChange={setVoiceSettings}
            onBack={()=>setView("main")}
          />
        )}
        {view==="account" && (
          <AccountView user={user} onBack={()=>setView("main")} />
        )}
        {view==="stats" && (
          <StatsView collection={collection} bonusXp={bonusXp} streak={streak} unlockedSecrets={unlockedSecrets} onBack={()=>setView("main")} />
        )}
        {view==="collections" && (
          <CollectionsView collection={collection} onBack={()=>setView("main")} />
        )}
        {view==="quiz" && (
          <QuizView
            collection={collection}
            onBack={()=>setView("main")}
          />
        )}
        {view==="enigma" && (
          <EnigmaView
            collection={collection}
            onBack={()=>setView("main")}
            onWin={(pts)=>setBonusXp(b => (b||0) + pts)}
          />
        )}
      </div>

      {view==="main"&&(
        <div style={{
          position:"fixed",bottom:0,left:"50%",transform:"translateX(-50%)",
          width:"100%",maxWidth:480,
          background:"#2B3320",borderTop:"3px solid #1a1f12",
          display:"grid",gridTemplateColumns:"1fr 1fr 1fr 1fr",
          zIndex:20,
        }}>
          {TABS.map(t=>(
            <button key={t.id} onClick={()=>setTab(t.id)} style={{
              background:tab===t.id?"#3a4528":"none",border:"none",cursor:"pointer",
              padding:"10px 0 12px",
              display:"flex",flexDirection:"column",alignItems:"center",gap:4,
              borderTop:tab===t.id?"3px solid #8FA869":"3px solid transparent",
            }}>
              <span style={{fontSize:20,transition:"transform 0.15s",transform:tab===t.id?"scale(1.15)":"scale(1)"}}>
                {t.icon}
              </span>
              <span style={{fontFamily:"'VT323',monospace",fontSize:15,color:tab===t.id?"#8FA869":"#6b7355"}}>
                {t.label}
              </span>
            </button>
          ))}
        </div>
      )}

      {view==="main"&&(tab==="home"||tab==="collection")&&(
        <button onClick={()=>setView("scan")} style={{
          position:"fixed",bottom:80,right:18,
          width:58,height:58,borderRadius:10,
          background:"linear-gradient(180deg,#f1c40f,#e0a800)",
          border:"3px solid #3a3f30",cursor:"pointer",fontSize:24,
          boxShadow:"0 5px 0 #3a3f30",
          display:"flex",alignItems:"center",justifyContent:"center",
          zIndex:15,
        }}>📷</button>
      )}

      {/* POPUP RÉCOMPENSE DE SÉRIE */}
      {streakReward && (
        <div onClick={()=>setStreakReward(null)} style={{
          position:"fixed",inset:0,zIndex:50,background:"rgba(0,0,0,0.7)",
          display:"flex",alignItems:"center",justifyContent:"center",padding:20,
        }}>
          <div style={{
            background:"linear-gradient(150deg,#e74c3c 0%,#c0392b 100%)",
            border:"4px solid #9E2B2F",borderRadius:14,padding:"6px",maxWidth:320,width:"100%",
            boxShadow:"0 12px 48px rgba(0,0,0,0.4)",animation:"bounce 0.6s ease",
          }}>
            <div style={{
              background:"#8FA869",border:"4px solid #3a3f30",borderRadius:8,
              padding:"28px 24px",textAlign:"center",position:"relative",overflow:"hidden",
              boxShadow:"inset 0 0 16px rgba(0,0,0,0.3)",
            }}>
              <div style={{position:"absolute",inset:0,pointerEvents:"none",
                background:"repeating-linear-gradient(0deg, rgba(0,0,0,0.06) 0px, rgba(0,0,0,0.06) 1px, transparent 1px, transparent 3px)"}}/>
              <div style={{fontSize:60,marginBottom:8,position:"relative"}}>{streakReward.icon}</div>
              <div style={{fontFamily:"'Press Start 2P',monospace",fontSize:13,color:"#2B3320",marginBottom:8,position:"relative"}}>
                {streakReward.title.toUpperCase()}
              </div>
              <div style={{fontFamily:"'VT323',monospace",fontSize:22,color:"#2B3320",marginBottom:6,position:"relative"}}>
                {streakReward.text}
              </div>
              <div style={{
                fontFamily:"'Press Start 2P',monospace",fontSize:12,color:"#D7363B",marginBottom:18,position:"relative",
              }}>
                +{streakReward.bonus} XP BONUS
              </div>
              <button onClick={()=>setStreakReward(null)} style={{
                background:"linear-gradient(180deg,#F4F0E4,#d8d2c0)",
                border:"3px solid #3a3f30",borderRadius:8,padding:"10px 28px",
                fontFamily:"'Press Start 2P',monospace",fontSize:11,color:"#2B3320",
                cursor:"pointer",boxShadow:"0 4px 0 #3a3f30",position:"relative",
              }}>GÉNIAL !</button>
            </div>
          </div>
        </div>
      )}

      {/* POPUP DÉFI ACCOMPLI */}
      {challengeDone && (
        <div onClick={()=>setChallengeDone(null)} style={{
          position:"fixed",inset:0,zIndex:50,background:"rgba(0,0,0,0.7)",
          display:"flex",alignItems:"center",justifyContent:"center",padding:20,
        }}>
          <div style={{
            background:"linear-gradient(150deg,#f1c40f 0%,#e0a800 100%)",
            border:"4px solid #b8860b",borderRadius:14,padding:"6px",maxWidth:320,width:"100%",
            boxShadow:"0 12px 48px rgba(0,0,0,0.4)",animation:"bounce 0.6s ease",
          }}>
            <div style={{
              background:"#8FA869",border:"4px solid #3a3f30",borderRadius:8,
              padding:"28px 24px",textAlign:"center",position:"relative",overflow:"hidden",
              boxShadow:"inset 0 0 16px rgba(0,0,0,0.3)",
            }}>
              <div style={{position:"absolute",inset:0,pointerEvents:"none",
                background:"repeating-linear-gradient(0deg, rgba(0,0,0,0.06) 0px, rgba(0,0,0,0.06) 1px, transparent 1px, transparent 3px)"}}/>
              <div style={{fontSize:56,marginBottom:8,position:"relative"}}>{challengeDone.icon}</div>
              <div style={{fontFamily:"'Press Start 2P',monospace",fontSize:14,color:"#2B3320",marginBottom:10,position:"relative"}}>
                DÉFI RÉUSSI !
              </div>
              <div style={{fontFamily:"'VT323',monospace",fontSize:20,color:"#2B3320",marginBottom:18,position:"relative",lineHeight:1.2}}>
                {challengeDone.text}
              </div>
              <button onClick={()=>setChallengeDone(null)} style={{
                background:"linear-gradient(180deg,#F4F0E4,#d8d2c0)",
                border:"3px solid #3a3f30",borderRadius:8,padding:"10px 28px",
                fontFamily:"'Press Start 2P',monospace",fontSize:11,color:"#2B3320",
                cursor:"pointer",boxShadow:"0 4px 0 #3a3f30",position:"relative",
              }}>BRAVO !</button>
            </div>
          </div>
        </div>
      )}

      {collectionDone && (
        <div onClick={()=>setCollectionDone(null)} style={{position:"fixed",inset:0,zIndex:50,background:"rgba(0,0,0,0.7)",display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
          <div style={{background:"linear-gradient(150deg,#9B59B6 0%,#7d3c98 100%)",border:"4px solid #5b2c6f",borderRadius:14,padding:"6px",maxWidth:320,width:"100%",boxShadow:"0 12px 48px rgba(0,0,0,0.4)",animation:"bounce 0.6s ease"}}>
            <div style={{background:"#8FA869",border:"4px solid #3a3f30",borderRadius:8,padding:"28px 24px",textAlign:"center",position:"relative",overflow:"hidden",boxShadow:"inset 0 0 16px rgba(0,0,0,0.3)"}}>
              <div style={{position:"absolute",inset:0,pointerEvents:"none",background:"repeating-linear-gradient(0deg, rgba(0,0,0,0.06) 0px, rgba(0,0,0,0.06) 1px, transparent 1px, transparent 3px)"}}/>
              <div style={{fontSize:56,marginBottom:8,position:"relative"}}>{collectionDone.icon}</div>
              <div style={{fontFamily:"'Press Start 2P',monospace",fontSize:13,color:"#2B3320",marginBottom:10,position:"relative"}}>COLLECTION COMPLÈTE !</div>
              <div style={{fontFamily:"'VT323',monospace",fontSize:22,color:"#2B3320",marginBottom:6,position:"relative",lineHeight:1.2}}>{collectionDone.name}</div>
              <div style={{fontFamily:"'Press Start 2P',monospace",fontSize:12,color:"#2e6e2e",marginBottom:18,position:"relative"}}>+{collectionDone.bonus} XP</div>
              <button onClick={()=>setCollectionDone(null)} style={{background:"linear-gradient(180deg,#F4F0E4,#d8d2c0)",border:"3px solid #3a3f30",borderRadius:8,padding:"10px 28px",fontFamily:"'Press Start 2P',monospace",fontSize:11,color:"#2B3320",cursor:"pointer",boxShadow:"0 4px 0 #3a3f30",position:"relative"}}>SUPER !</button>
            </div>
          </div>
        </div>
      )}

      {/* POPUP LEVEL UP */}
      {justLeveledUp && (
        <div onClick={()=>setJustLeveledUp(null)} style={{
          position:"fixed",inset:0,zIndex:50,
          background:"rgba(0,0,0,0.7)",
          display:"flex",alignItems:"center",justifyContent:"center",
          padding:20,
        }}>
          <div style={{
            background:"linear-gradient(150deg,#D7363B 0%,#B82A2F 100%)",
            border:"4px solid #9E2B2F",borderRadius:14,
            padding:"6px",maxWidth:320,width:"100%",
            boxShadow:"0 12px 48px rgba(0,0,0,0.4)",
            animation:"bounce 0.6s ease",
          }}>
            <div style={{
              background:"#8FA869",border:"4px solid #3a3f30",borderRadius:8,
              padding:"28px 24px",textAlign:"center",position:"relative",overflow:"hidden",
              boxShadow:"inset 0 0 16px rgba(0,0,0,0.3)",
            }}>
              <div style={{
                position:"absolute",inset:0,pointerEvents:"none",
                background:"repeating-linear-gradient(0deg, rgba(0,0,0,0.06) 0px, rgba(0,0,0,0.06) 1px, transparent 1px, transparent 3px)",
              }}/>
              <div style={{fontSize:60,marginBottom:4,position:"relative",lineHeight:1}}>
                <span>{mascotForLevel(justLeveledUp.lvl).emoji}</span>
                {mascotForLevel(justLeveledUp.lvl).accessory && (
                  <span style={{fontSize:30,marginLeft:-6}}>{mascotForLevel(justLeveledUp.lvl).accessory}</span>
                )}
              </div>
              <div style={{fontFamily:"'VT323',monospace",fontSize:18,color:"#2B3320",marginBottom:6,position:"relative"}}>
                {mascotForLevel(justLeveledUp.lvl).name}
              </div>
              <div style={{fontFamily:"'Press Start 2P',monospace",fontSize:16,color:"#2B3320",marginBottom:8,position:"relative"}}>
                NIVEAU {justLeveledUp.lvl} !
              </div>
              <div style={{fontFamily:"'Press Start 2P',monospace",fontSize:11,color:"#2B3320",marginBottom:14,position:"relative"}}>
                {justLeveledUp.title.toUpperCase()}
              </div>
              <div style={{fontFamily:"'VT323',monospace",fontSize:19,color:"#2B3320",marginBottom:18,position:"relative",lineHeight:1.2}}>
                Tu progresses comme un vrai explorateur de la nature !
              </div>
              <button onClick={()=>setJustLeveledUp(null)} style={{
                background:"linear-gradient(180deg,#F4F0E4,#d8d2c0)",
                border:"3px solid #3a3f30",borderRadius:8,padding:"10px 28px",
                fontFamily:"'Press Start 2P',monospace",fontSize:11,color:"#2B3320",
                cursor:"pointer",boxShadow:"0 4px 0 #3a3f30",position:"relative",
              }}>SUPER !</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
